const root = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9cbbf');
scene.fog = new THREE.FogExp2('#a9cbbf', 0.0037);
const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, .1, 420);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.14;
root.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight('#e5f4e3', '#556b48', 2.0));
const sun = new THREE.DirectionalLight('#ffe3ae', 3.1);
sun.position.set(-45, 80, 35);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -100; sun.shadow.camera.right = 100;
sun.shadow.camera.top = 100; sun.shadow.camera.bottom = -100;
sun.shadow.normalBias = 0.035;
scene.add(sun);

const mat = (color, roughness = .9, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const groundMat = mat('#78966b');
const terrainHeight = (x, z) => {
  const hills = Math.sin(x * .045 + Math.sin(z * .023)) * 1.15 + Math.cos(z * .052) * .8 + Math.sin((x + z) * .027) * .7;
  const hillA = 5.2 * Math.exp(-((x - 57) ** 2 + (z + 32) ** 2) / 850);
  const hillB = 4.0 * Math.exp(-((x + 62) ** 2 + (z - 45) ** 2) / 1000);
  const clearing = -1.0 * Math.exp(-(x * x + z * z) / 1000);
  return hills + hillA + hillB + clearing;
};
const size = 250, segments = 170;
const groundGeo = new THREE.PlaneGeometry(size, size, segments, segments);
groundGeo.rotateX(-Math.PI / 2);
const pos = groundGeo.attributes.position;
for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i), z = pos.getZ(i);
  pos.setY(i, terrainHeight(x, z));
}
groundGeo.computeVertexNormals();
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.receiveShadow = true;
scene.add(ground);

// Soft distant mountain silhouettes ring the walkable valley.
const mountainMat = mat('#849f91');
const farMat = mat('#9bb5a7');
for (let i = 0; i < 38; i++) {
  const a = i / 38 * Math.PI * 2;
  const r = 141 + Math.sin(i * 19.3) * 7;
  const h = 18 + (Math.sin(i * 9.7) + 1) * 9;
  const g = new THREE.ConeGeometry(13 + (i % 3) * 3, h, 5);
  const m = new THREE.Mesh(g, i % 2 ? mountainMat : farMat);
  m.position.set(Math.cos(a) * r, h * .28 - 3, Math.sin(a) * r);
  m.rotation.y = a;
  m.scale.y = .8;
  scene.add(m);
}

// A warmly-lit sky, distant cloud wisps, and a tiny flock overhead.
const sunBall = new THREE.Mesh(new THREE.SphereGeometry(3.2, 20, 16), new THREE.MeshBasicMaterial({ color: '#ffe6ad' }));
sunBall.position.set(-70, 72, -130); scene.add(sunBall);
const cloudMat = new THREE.MeshBasicMaterial({ color: '#f1f0d7', transparent: true, opacity: .43, depthWrite: false });
for (let i = 0; i < 11; i++) {
  const cloud = new THREE.Group();
  for (let j = 0; j < 5; j++) {
    const puff = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 7), cloudMat);
    puff.scale.set(4 + Math.sin(i * 4 + j) * 1.5, .65 + (j % 2) * .2, 1.4);
    puff.position.set(j * 3.5 - 7, Math.sin(j * 1.7) * .7, Math.cos(j) * .7);
    cloud.add(puff);
  }
  cloud.position.set(-115 + (i * 47) % 220, 32 + (i * 13) % 16, -100 + (i * 61) % 200);
  scene.add(cloud);
}

