// A winding footpath connects the quiet starting glade to the old Starwell.
const trailPoints = [new THREE.Vector3(0,0,9), new THREE.Vector3(2,0,-8), new THREE.Vector3(-3,0,-24), new THREE.Vector3(4,0,-41), new THREE.Vector3(0,0,-59), new THREE.Vector3(-2,0,-79), new THREE.Vector3(0,0,-100)];
const trailCurve = new THREE.CatmullRomCurve3(trailPoints);
const trailVerts = [], trailIndex = [];
for (let i = 0; i <= 160; i++) {
  const t = i / 160, p = trailCurve.getPoint(t), tangent = trailCurve.getTangent(t);
  const side = new THREE.Vector3(-tangent.z, 0, tangent.x).normalize();
  for (const w of [-1.7, 1.7]) trailVerts.push(p.x + side.x * w, terrainHeight(p.x + side.x * w, p.z + side.z * w) + .1, p.z + side.z * w);
  if (i < 160) { const n = i * 2; trailIndex.push(n,n+1,n+2,n+1,n+3,n+2); }
}
const trailGeo = new THREE.BufferGeometry();
trailGeo.setAttribute('position', new THREE.Float32BufferAttribute(trailVerts, 3)); trailGeo.setIndex(trailIndex); trailGeo.computeVertexNormals();
const trail = new THREE.Mesh(trailGeo, new THREE.MeshStandardMaterial({ color: '#b8a77c', roughness: 1, side: THREE.DoubleSide }));
trail.receiveShadow = true; scene.add(trail);

// A whole forest in just a few draw calls: richly layered low-poly canopies.
let seed = 87219;
const random = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
const shardSpots = [[-43,-36],[52,-42],[-70,43],[69,49],[7,-83]];
const trunkGeo = new THREE.CylinderGeometry(.28,.44,1,7);
const leafGeos = [new THREE.ConeGeometry(1.45,2.4,7), new THREE.ConeGeometry(1.18,2.15,7), new THREE.ConeGeometry(.86,1.8,7)];
const trunkInst = new THREE.InstancedMesh(trunkGeo, mat('#70523b'), 245);
const leafMats = [mat('#426b4c'),mat('#537a50'),mat('#628658')];
const leafInst = leafGeos.map((geo,i) => new THREE.InstancedMesh(geo, leafMats[i],245));
trunkInst.castShadow = true; trunkInst.receiveShadow = true;
leafInst.forEach(m => {m.castShadow = true; m.receiveShadow = true;});
const dummy = new THREE.Object3D();
let treeCount = 0;
for (let tries = 0; tries < 1800 && treeCount < 245; tries++) {
  const x = (random() - .5) * 225, z = (random() - .5) * 225;
  if (Math.hypot(x,z) < 14 || shardSpots.some(([sx,sz]) => Math.hypot(x-sx,z-sz) < 9)) continue;
  const trailP = trailCurve.getPoints(90);
  let nearest = 999;
  for (let k=0;k<trailP.length;k+=3) nearest = Math.min(nearest, Math.hypot(x-trailP[k].x,z-trailP[k].z));
  if (nearest < 4.1) continue;
  const y = terrainHeight(x,z), scale = .72 + random() * .75;
  dummy.position.set(x,y+.9*scale,z); dummy.scale.set(scale,scale*1.65,scale); dummy.rotation.set(0,random()*Math.PI,0); dummy.updateMatrix(); trunkInst.setMatrixAt(treeCount,dummy.matrix);
  for (let layer=0;layer<3;layer++) {
    dummy.position.set(x,y+(2.0+layer*1.08)*scale,z); dummy.scale.set(scale*(1-layer*.11),scale*(1-layer*.11),scale*(1-layer*.11)); dummy.rotation.set(0,random()*Math.PI,0); dummy.updateMatrix(); leafInst[layer].setMatrixAt(treeCount,dummy.matrix);
    const shade = .86 + random()*.25; leafInst[layer].setColorAt(treeCount,new THREE.Color().setRGB(shade,shade,shade));
  }
  treeCount++;
}
trunkInst.count = treeCount; trunkInst.instanceMatrix.needsUpdate = true; scene.add(trunkInst);
leafInst.forEach(m => {m.count=treeCount;m.instanceMatrix.needsUpdate=true;scene.add(m);});

// Ferns, sunlit field flowers, and scattered stones add detail near the trail.
const stoneGeo = new THREE.DodecahedronGeometry(1,0);
const stones = new THREE.InstancedMesh(stoneGeo, mat('#8b9278'), 90);
for (let i=0;i<90;i++) {
  const x=(random()-.5)*190,z=(random()-.5)*190;
  dummy.position.set(x,terrainHeight(x,z)+.2,z); dummy.rotation.set(random(),random()*3,random());
  dummy.scale.set(.25+random()*.7,.2+random()*.35,.25+random()*.55); dummy.updateMatrix(); stones.setMatrixAt(i,dummy.matrix);
  const shade=.8+random()*.3; stones.setColorAt(i,new THREE.Color().setRGB(shade,shade,shade));
}
stones.castShadow=true;stones.receiveShadow=true;scene.add(stones);
const flowerGeo = new THREE.SphereGeometry(.11,7,5);
const flowerColors=['#e7d28f','#d4a9a0','#ede4c4','#d29a55'];
for(let f=0;f<4;f++){
  const blooms=new THREE.InstancedMesh(flowerGeo,mat(flowerColors[f]),44);
  for(let i=0;i<44;i++){
    const x=(random()-.5)*150,z=(random()-.5)*150;
    dummy.position.set(x,terrainHeight(x,z)+.22,z);dummy.scale.set(1,1+random()*1.7,1);dummy.updateMatrix();blooms.setMatrixAt(i,dummy.matrix);
  }
  scene.add(blooms);
}

