const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:'#f4d99b',size:.13,transparent:true,opacity:.68,sizeAttenuation:true}));scene.add(dust);

const keys=new Set();
let yaw=0,cameraYaw=0,cameraPitch=.23,cameraDistance=7.6,verticalVelocity=0,onGround=true,stamina=1,found=0,started=false,won=false;
const velocity=new THREE.Vector3(), moveDirection=new THREE.Vector3();
const intro=document.querySelector('#intro'), toast=document.querySelector('#toast');
let toastTimer;
function announce(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2300);}
function startGame(){started=true;intro.classList.add('hidden');}
document.querySelector('#startButton').addEventListener('click',startGame);
window.addEventListener('keydown',e=>{keys.add(e.code);if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'&&onGround){verticalVelocity=7.2;onGround=false;}});
window.addEventListener('keyup',e=>keys.delete(e.code));
window.addEventListener('blur',()=>keys.clear());

let dragging=false,lastX=0,lastY=0;
renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;dragging=true;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId);});
renderer.domElement.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;cameraYaw-=dx*.004;cameraPitch=THREE.MathUtils.clamp(cameraPitch+dy*.0025,-.05,.72);});
renderer.domElement.addEventListener('pointerup',()=>dragging=false);
renderer.domElement.addEventListener('pointercancel',()=>dragging=false);
renderer.domElement.addEventListener('wheel',e=>{cameraDistance=THREE.MathUtils.clamp(cameraDistance+e.deltaY*.008,4.7,12);},{passive:true});

const stickPad=document.querySelector('#joystick'),stick=document.querySelector('#stick');
let stickX=0,stickY=0,stickPointer=null;
function updateStick(e){const r=stickPad.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),scale=Math.min(1,len/43);stickX=dx/(len||1)*scale;stickY=dy/(len||1)*scale;stick.style.transform=`translate(calc(-50% + ${stickX*34}px),calc(-50% + ${stickY*34}px))`;}
stickPad.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stickPad.setPointerCapture(e.pointerId);updateStick(e);});
stickPad.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)updateStick(e);});
function resetStick(){stickPointer=null;stickX=stickY=0;stick.style.transform='translate(-50%,-50%)';}
stickPad.addEventListener('pointerup',resetStick);stickPad.addEventListener('pointercancel',resetStick);
document.querySelector('#jumpButton').addEventListener('pointerdown',e=>{e.preventDefault();if(onGround){verticalVelocity=7.2;onGround=false;}});

const progressFill=document.querySelector('#progressFill'),progressText=document.querySelector('#progressText');
const questTitle=document.querySelector('#questTitle'),interact=document.querySelector('#interact');
interact.addEventListener('click',()=>enterStarwell());
function enterStarwell(){if(found<5){announce('The Starwell needs all five starshards.');return;}if(won)return;won=true;announce('The Starwell awakens — the valley remembers!');portalLight.intensity=8;portalRing.material.emissiveIntensity=2;portalCore.material.opacity=.6;questTitle.textContent='The valley remembers';interact.classList.remove('show');setTimeout(()=>{
  intro.querySelector('.eyebrow').textContent='Journey complete';
  intro.querySelector('h1').innerHTML='THE LIGHT<br>RETURNS';
  intro.querySelector('p').textContent='You gathered the starshards and woke the ancient Starwell. The forest glows again. Take your time — the wilds are yours to explore.';
  document.querySelector('#startButton').textContent='Return to the wilds';
  intro.classList.remove('hidden');
},900);}

const mapCanvas=document.querySelector('#minimap'),mapCtx=mapCanvas.getContext('2d');
function drawMap(){
  const c=mapCtx;c.clearRect(0,0,140,140);c.save();c.beginPath();c.arc(70,70,69,0,Math.PI*2);c.clip();
  c.fillStyle='#426451';c.fillRect(0,0,140,140);
  for(let i=0;i<32;i++){const x=(i*67+13)%140,y=(i*43+29)%140;c.fillStyle=i%2?'#58755c':'#4c6a55';c.beginPath();c.arc(x,y,4+(i%4),0,Math.PI*2);c.fill();}
  const point=(x,z)=>[70+x/250*140,70+z/250*140];
  c.strokeStyle='#c2ad7b';c.lineWidth=2;c.beginPath();trailSamples.forEach((p,i)=>{const [x,y]=point(p.x,p.z);if(i===0)c.moveTo(x,y);else c.lineTo(x,y);});c.stroke();
  shards.forEach(s=>{if(s.collected)return;const [x,y]=point(s.group.position.x,s.group.position.z);c.fillStyle='#f8d77f';c.beginPath();c.arc(x,y,2.4,0,Math.PI*2);c.fill();});
  const [px,py]=point(player.position.x,player.position.z);c.translate(px,py);c.rotate(yaw);c.fillStyle='#fff4c8';c.beginPath();c.moveTo(0,-5);c.lineTo(3.5,4);c.lineTo(0,2);c.lineTo(-3.5,4);c.closePath();c.fill();c.restore();
}

const clock=new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const dt=Math.min(clock.getDelta(),.035),time=clock.elapsedTime;
  const forward=(keys.has('KeyW')||keys.has('ArrowUp')?-1:0)+(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-stickY;
  const sideways=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+stickX;
  moveDirection.set(0,0,0);
  const fwd=new THREE.Vector3(Math.sin(cameraYaw),0,-Math.cos(cameraYaw));
  const right=new THREE.Vector3(Math.cos(cameraYaw),0,Math.sin(cameraYaw));
  moveDirection.addScaledVector(fwd,forward).addScaledVector(right,sideways);
  if(moveDirection.lengthSq()>1)moveDirection.normalize();
  const sprint=(keys.has('ShiftLeft')||keys.has('ShiftRight'))&&moveDirection.lengthSq()>.1&&stamina>.02;
  const speed=sprint?8.3:4.7;
  if(started){
    player.position.x=THREE.MathUtils.clamp(player.position.x+moveDirection.x*speed*dt,-116,116);
    player.position.z=THREE.MathUtils.clamp(player.position.z+moveDirection.z*speed*dt,-116,116);
    const floor=terrainHeight(player.position.x,player.position.z);
    if(sprint)stamina=Math.max(0,stamina-dt*.17);else stamina=Math.min(1,stamina+dt*.11);
    if(!onGround){verticalVelocity-=18*dt;player.position.y+=verticalVelocity*dt;if(player.position.y<=floor){player.position.y=floor;verticalVelocity=0;onGround=true;}}
    else player.position.y=THREE.MathUtils.lerp(player.position.y,floor,Math.min(1,dt*12));
    if(moveDirection.lengthSq()>.01){yaw=Math.atan2(moveDirection.x,-moveDirection.z);avatar.rotation.y=THREE.MathUtils.lerp(avatar.rotation.y,yaw,Math.min(1,dt*10));}
  }
  const moving=moveDirection.lengthSq()>.01&&started;
  avatar.position.y=moving&&onGround?Math.abs(Math.sin(time*(sprint?13:9)))*.07:0;
  legs.forEach((leg,i)=>leg.rotation.x=moving?Math.sin(time*(sprint?13:9)+i*Math.PI)*.52:THREE.MathUtils.lerp(leg.rotation.x,0,dt*8));
  arms.forEach((arm,i)=>arm.rotation.x=moving?Math.sin(time*(sprint?13:9)+Math.PI+i*Math.PI)*.42:THREE.MathUtils.lerp(arm.rotation.x,0,dt*8));
  shards.forEach(s=>{if(s.collected)return;s.group.position.y=s.baseY+Math.sin(time*1.65+s.phase)*.22;s.group.rotation.y=time*.55+s.phase;s.halo.rotation.z=time*.8+s.phase;
    if(started&&player.position.distanceTo(s.group.position)<2.15){s.collected=true;scene.remove(s.group);found++;progressText.textContent=`${found} / 5`;progressFill.style.width=`${found*20}%`;announce(['A starshard hums in your palm','A second light joins your path','The wilds answer your call','Only one shard remains','All five starshards are yours'][found-1]);if(found===5){questTitle.textContent='Return to the Starwell';portalRing.material.emissiveIntensity=.9;portalCore.material.opacity=.24;portalLight.intensity=2.5;}}
  });
  const portalDistance=Math.hypot(player.position.x,player.position.z+103);
  interact.classList.toggle('show',started&&portalDistance<8);
  if(started&&found===5&&portalDistance<4.2)enterStarwell();
  portalRing.rotation.z=Math.sin(time*.6)*.025;
  portalCore.material.opacity=won?.55:(found===5?.18:.045);
  portalLight.intensity=won?7:(found===5?2.1:0);
  portalRing.material.emissiveIntensity=won?2:(found===5?.7:0);
  for(let i=0;i<cloudsLength();i++){} // clouds stay distant and peaceful
  const desired=new THREE.Vector3(
    player.position.x+Math.sin(cameraYaw)*cameraDistance*Math.cos(cameraPitch),
    player.position.y+2.6+cameraDistance*Math.sin(cameraPitch),
    player.position.z+Math.cos(cameraYaw)*cameraDistance*Math.cos(cameraPitch)
  );
  camera.position.lerp(desired,Math.min(1,dt*5.2));
  camera.lookAt(player.position.x,player.position.y+1.35,player.position.z);
  document.querySelector('#staminaFill').style.width=`${Math.round(stamina*100)}%`;
  if(Math.floor(time*8)%2===0)drawMap();
  renderer.render(scene,camera);
}
function cloudsLength(){return 0;}

function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);}
window.addEventListener('resize',resize);
player.position.set(0,terrainHeight(0,9),9);
camera.position.set(0,5,17);camera.lookAt(0,1.3,9);
drawMap();animate();

